/**
 * Agent 안의 초점. Agent 창이 입력창에 초점을 주는 함수를 context 로 내밀고, 그 안에서 열리는 팝오버
 * (모드 · 모델 · 기록)는 닫힐 때 칩 대신 입력창으로 초점을 돌려준다. Agent 밖에서 쓰인 같은 팝오버는
 * context 가 없으므로 원래대로 트리거에 돌려준다.
 */
import { getContext, setContext } from "svelte";

const KEY = Symbol("agent-focus");

export function provideAgentFocus(focus: () => void) {
	setContext(KEY, focus);
}

/**
 * 팝오버 `onCloseAutoFocus` 에 넘긴다. Agent 밖이면 undefined(기본 동작).
 * 닫힌 뒤 초점이 몸통 · 닫히는 상자 · 닫힌 트리거에 남았을 때만 입력창으로 옮긴다: 다른 곳을 눌러 닫았으면 그대로 둔다.
 */
export function agentCloseFocus(): ((event: Event) => void) | undefined {
	const focus = getContext<(() => void) | undefined>(KEY);
	if (!focus) return undefined;
	return (event) => {
		/* 다른 팝오버 안에 겹쳐 열린 것(모델 상자의 manual 칸)은 제 트리거로: 입력창으로 가면 바깥 상자가 닫힌다. */
		if (document.querySelectorAll("[data-slot=popover-content]").length > 1) return;
		event.preventDefault();
		requestAnimationFrame(() => {
			/* 닫히는 상자는 나가는 움직임 동안 아직 DOM 에 있어 초점이 그 안에 남아 있을 수 있다. */
			const active = document.activeElement;
			if (
				!active ||
				active === document.body ||
				active.closest("[data-slot=popover-content]") ||
				active.getAttribute("aria-expanded") === "false"
			)
				focus();
		});
	};
}

/**
 * 하네스 = 명령을 실제로 돌리는 CLI. 모델 목록과 effort 목록은 하네스가 정한다.
 *
 * - `pi`: 서버가 Pi 설정에서 읽어 주는 카탈로그(`GET /api/pi/models`). 로그인된 provider만.
 * - `claude`: Claude Code CLI(`claude -p --model {id} --effort {level}`). 모델은 서버가 Anthropic에서
 *   읽어 주는 카탈로그(`GET /api/claude/models`)이고, 인증은 `~/.claude/.credentials.json` 한 곳이다
 *   (`.agents/rules/providers.md`).
 *
 * 기획: `docs/plan/260928-worktree-workflow.md` §1.
 */
import { claudeCatalog } from "$lib/projects/claude-models.svelte.js";
import {
	clampPiEffort,
	piEffortsFor,
	piPickerItems,
	type PiEffort,
	type PiPickerItem,
	type PiProvider,
	withCurrentModel,
} from "$lib/projects/pi-models.js";

export type Harness = "pi" | "claude";
export const HARNESSES: Harness[] = ["pi", "claude"];

/** 역할 하나의 선택. Worker는 worktree 작업, Lead는 검토와 plain 명령. */
export type RoleModel = { harness: Harness; model: string; effort: string };
/** 컴포저의 `auto`: 항목마다 그 하네스의 켜진 등급 전부에서 model_route 가 고른다(서버 `tiered::auto`). */
export const AUTO_MODEL = "auto";
export function autoModel(harness: Harness): RoleModel {
	return { harness, model: AUTO_MODEL, effort: "" };
}
export function isAuto(role: RoleModel | null | undefined) {
	return role?.model === AUTO_MODEL;
}
/** `workerFallbacks` · `leadFallbacks`: 주 모델이 시작 전에 거부하거나 말이 없으면 그 순서대로 한 번씩 다시 돈다. */
export type ModelSelection = {
	worker: RoleModel;
	lead: RoleModel;
	workerFallbacks: RoleModel[];
	leadFallbacks: RoleModel[];
	/** 역할 하네스의 `tiers.json` 목록에서 쓸 등급 범위: 작업마다 그 안에서 고른다(서버 `tiered.rs`).
	 *  서버가 내려주는 `worker` · `lead` 는 이미 등급을 푼 값이다. 없으면 위 모델을 그대로 쓴다. */
	workerTiers?: { from: string; to: string };
	leadTiers?: { from: string; to: string };
};

/** 한 역할이 주 모델 말고 더 고를 수 있는 수. */
export const MAX_FALLBACKS = 5;

export const CLAUDE_EFFORTS = ["low", "medium", "high", "xhigh", "max"] as const;
export const DEFAULT_MODELS: ModelSelection = {
	worker: { harness: "pi", model: "opencode-go/deepseek-v4.1-flash", effort: "high" },
	lead: { harness: "claude", model: "Opus 5.5", effort: "medium" },
	workerFallbacks: [],
	leadFallbacks: [],
};

export function modelItems(harness: Harness, providers: PiProvider[], current?: string): PiPickerItem[] {
	/* 목록과 저장값은 화면 이름(`name`)이다. CLI id로는 서버가 바꾼다. */
	if (harness === "claude") return claudeCatalog.models.map((model) => ({ value: model.name, group: "Claude Code" }));
	return withCurrentModel(piPickerItems(providers), providers, current);
}

export function effortsFor(harness: Harness, providers: PiProvider[], model: string): string[] {
	if (harness === "claude") return [...CLAUDE_EFFORTS];
	return piEffortsFor(providers, model);
}

/** 하네스나 모델을 바꾸면 없는 effort를 가장 가까운 지원 레벨로 내린다(Pi `clampThinkingLevel` 규칙). */
export function clampEffort(harness: Harness, providers: PiProvider[], model: string, effort: string): string {
	return clampPiEffort(effortsFor(harness, providers, model) as PiEffort[], effort);
}

/** 하네스를 바꾸면 그 하네스의 첫 모델로 옮긴다. 같은 하네스로 돌아오면 기본값. */
export function switchHarness(
	role: RoleModel,
	harness: Harness,
	providers: PiProvider[],
	fallback: RoleModel,
): RoleModel {
	if (role.harness === harness) return role;
	const items = modelItems(harness, providers);
	const model = fallback.harness === harness ? fallback.model : (items[0]?.value ?? "");
	return { harness, model, effort: clampEffort(harness, providers, model, role.effort) };
}

/** 추가할 모델 하나: 주 모델과 이미 고른 모델을 빼고, 주 모델의 하네스에서 아직 안 쓴 모델을 고른다.
 *  그 하네스가 다 썼으면 반대 하네스로 넘어간다. 없으면 추가할 수 없다. */
export function nextFallback(primary: RoleModel, taken: RoleModel[], providers: PiProvider[]): RoleModel | null {
	const used = (model: string) => model === primary.model || taken.some((entry) => entry.model === model);
	const other: Harness = primary.harness === "pi" ? "claude" : "pi";
	for (const harness of [primary.harness, other] as Harness[]) {
		const model = modelItems(harness, providers).find((item) => !used(item.value))?.value;
		if (model)
			return {
				harness,
				model,
				effort: clampEffort(harness, providers, model, primary.effort),
			};
	}
	return null;
}

/** 컴포저 필: `pi · deepseek-v4.1-flash · high`. provider 접두사는 title로만 남는다. */
export function shortModel(role: RoleModel): string {
	const name = role.harness === "claude" ? role.model : role.model.split("/").slice(1).join("/") || role.model;
	return `${role.harness} · ${name} · ${role.effort}`;
}

export function fullModel(role: RoleModel): string {
	return `${role.harness} ${role.model} (${role.effort})`;
}

/**
 * `/projects` 셸 탭 하나의 창(pane) 배치: 오른쪽·아래로 나눈 이진 트리. 잎마다 서버 셸 하나가 붙는다.
 * 첫 잎의 id 는 `ROOT_PANE` 이라 나누기 전 탭의 세션 id 가 그대로 이어진다(이미 도는 셸이 끊기지 않는다).
 * 모든 함수는 새 트리를 돌려준다(상태는 `$state` 에 통째로 다시 넣는다).
 */

/** `n` 은 서버가 매긴 고정 번호(`#프로젝트:n`), `session` 은 그 창의 터미널(master 첫 셸 탭만, 서버가 `#n` 을
 *  풀 때 쓴다). 나눈 직후의 새 잎은 서버가 번호를 줄 때까지 `n` 이 없다(261026 §8). */
export type PaneLeaf = { kind: "leaf"; id: string; n?: number; session?: string };
/** `row` = 왼쪽|오른쪽, `col` = 위/아래. `ratio` 는 `a` 의 몫(0~1). `tail` = 서버가 붙인 창들(`b`)의 뿌리. */
export type PaneSplit = {
	kind: "split";
	dir: "row" | "col";
	ratio: number;
	a: PaneNode;
	b: PaneNode;
	tail?: boolean;
};
export type PaneNode = PaneLeaf | PaneSplit;

export const ROOT_PANE = "root";
export const MIN_RATIO = 0.1;

export const singlePane = (): PaneNode => ({ kind: "leaf", id: ROOT_PANE });

export function leaves(node: PaneNode): PaneLeaf[] {
	return node.kind === "leaf" ? [node] : [...leaves(node.a), ...leaves(node.b)];
}

/** `target` 잎을 둘로 나눠 오른쪽(`row`)·아래(`col`)에 `id` 잎을 둔다. */
export function splitPane(node: PaneNode, target: string, dir: "row" | "col", id: string): PaneNode {
	if (node.kind === "leaf")
		return node.id === target ? { kind: "split", dir, ratio: 0.5, a: node, b: { kind: "leaf", id } } : node;
	return { ...node, a: splitPane(node.a, target, dir, id), b: splitPane(node.b, target, dir, id) };
}

/** 탭 전체를 n×n 격자로 다시 짠다. 기존 잎은 행 우선으로 앞 칸부터 채워 그 셸 · 번호가 이어지고, 남는 칸만
 *  `mint` 가 만든 새 id 를 쓴다. 칸보다 잎이 많으면 뒤쪽은 `dropped` 로 돌려준다(부르는 쪽이 세션을 끝낸다). */
export function gridPane(
	existing: (string | PaneLeaf)[],
	n: number,
	mint: (index: number) => string,
): { panes: PaneNode; dropped: string[] } {
	const cells = n * n;
	const kept = existing.map((leaf): PaneLeaf => (typeof leaf === "string" ? { kind: "leaf", id: leaf } : leaf));
	const used = new Set(kept.map((leaf) => leaf.id));
	const cellsOf = Array.from({ length: cells }, (_, index): PaneLeaf => {
		if (index < kept.length) return kept[index];
		let id = mint(index);
		while (used.has(id)) id += "x";
		used.add(id);
		return { kind: "leaf", id };
	});
	const chain = (nodes: PaneNode[], dir: "row" | "col") =>
		nodes.reduceRight((b, a): PaneNode => ({ kind: "split", dir, ratio: 0.5, a, b }));
	const rows = Array.from({ length: n }, (_, row) => chain(cellsOf.slice(row * n, (row + 1) * n), "row"));
	return { panes: equalize(chain(rows, "col")), dropped: kept.slice(cells).map((leaf) => leaf.id) };
}

/** Agent 창(서버 `workflow/panes.rs`)의 잎 id: `agent3`. 사람이 나눈 잎(`p…`)과 겹치지 않는다. */
export const agentLeaf = (n: number) => `agent${n}`;

export function agentPaneNumber(id: string): number | null {
	const match = /^agent([1-9])$/.exec(id);
	return match ? Number(match[1]) : null;
}

/** worktree 태스크의 Worker TUI 잎 id: `wt-02`. master 첫 셸 탭에서 Agent 창과 같은 열에 선다. */
export const worktreeLeaf = (task: string) => `wt-${task}`;

export function worktreeLeafTask(id: string): string | null {
	return id.startsWith("wt-") ? id.slice(3) : null;
}

/** 서버가 여닫는 잎(Agent 창 · worktree 창). 나머지는 사람이 나눈 창이다. */
export const serverLeaf = (id: string) => agentPaneNumber(id) !== null || worktreeLeafTask(id) !== null;

/** 트리의 번호 붙은 잎들, 번호 순. */
export function numberedLeaves(node: PaneNode): (PaneLeaf & { n: number })[] {
	return leaves(node)
		.filter((leaf): leaf is PaneLeaf & { n: number } => typeof leaf.n === "number")
		.toSorted((a, b) => a.n - b.n);
}

/** 서버가 `#n` 을 풀 수 있게 사람 잎마다 세션을 싣는다(서버 잎의 세션은 서버가 싣는다). */
export function stampSessions(node: PaneNode, sessionOf: (id: string) => string): PaneNode {
	if (node.kind === "leaf")
		return serverLeaf(node.id) || node.session === sessionOf(node.id) ? node : { ...node, session: sessionOf(node.id) };
	return { ...node, a: stampSessions(node.a, sessionOf), b: stampSessions(node.b, sessionOf) };
}

/** `target` 잎을 빼고 형제가 부모 자리를 맡는다. 마지막 잎이면 null(탭을 닫는다). */
export function closePane(node: PaneNode, target: string): PaneNode | null {
	if (node.kind === "leaf") return node.id === target ? null : node;
	const a = closePane(node.a, target);
	const b = closePane(node.b, target);
	if (!a) return b;
	if (!b) return a;
	return { ...node, a, b };
}

/** 같은 방향으로 이어진 잎들이 같은 폭을 갖도록 비율을 다시 매긴다. */
export function equalize(node: PaneNode): PaneNode {
	if (node.kind === "leaf") return node;
	const weight = (child: PaneNode): number =>
		child.kind === "split" && child.dir === node.dir ? weight(child.a) + weight(child.b) : 1;
	const a = weight(node.a);
	return { ...node, ratio: a / (a + weight(node.b)), a: equalize(node.a), b: equalize(node.b) };
}

/** 트리 경로(`a`/`b` 의 나열)로 찾은 나눔의 비율을 바꾼다. 끌기 손잡이가 쓴다. */
export function setRatio(node: PaneNode, path: string, ratio: number): PaneNode {
	if (node.kind === "leaf") return node;
	if (path === "") return { ...node, ratio: Math.min(1 - MIN_RATIO, Math.max(MIN_RATIO, ratio)) };
	const [step, rest] = [path[0], path.slice(1)];
	return step === "a" ? { ...node, a: setRatio(node.a, rest, ratio) } : { ...node, b: setRatio(node.b, rest, ratio) };
}

