/**
 * 터미널 창 제목에서 현재 태스크(세션 주제)를 뽑는다. 하네스마다 제목 꼴이 다르다:
 *
 * - `claude`: 스피너 글리프 뒤에 주제가 붙는다(`✳ Terminal blind overlay`). 스피너가 없는
 *   `Claude Code` 는 기본 제목이라 태스크가 없다.
 * - `pi`: `<앱> - <세션 이름> - <폴더>` 꼴이다(`π - fix login - dashboard`). 가운데가 없으면
 *   (`π - dashboard`) 태스크가 없다.
 *
 * 태스크가 없으면 null 을 돌aturation 돌려준다(호출 쪽은 기본 표시로 둔다).
 */
const CLAUDE_DEFAULT = "Claude Code";

/** Claude Code 스피너 글리프: `✳` 류(2733 등)와 점자 스피너(2800–28FF, 예: `⠂`). */
const SPINNER = /^[✳✻✼✽✾✿❀❁❃❇⠀-⣿]\s*/u;

export function taskTitle(harness: string, rawTitle: string): string | null {
	const title = rawTitle.trim();
	if (!title) return null;

	if (harness === "claude") {
		const topic = title.replace(SPINNER, "").trim();
		if (!topic || topic === CLAUDE_DEFAULT) return null;
		return topic;
	}

	if (harness === "pi") {
		const parts = title.split(" - ");
		if (parts.length < 3) return null;
		const session = parts.slice(1, -1).join(" - ").trim();
		return session || null;
	}

	return null;
}
